SELECT e.*, c.category_name FROM equipment e LEFT JOIN equipment_category c ON e.category_id = c.id
AND e.name LIKE CONCAT('%', #{name}, '%')
AND e.category_id = #{categoryId}
AND e.brand LIKE CONCAT('%', #{brand}, '%')
AND e.status = #{status}
ORDER BY e.created_at DESC

SELECT COUNT(*) FROM equipment e


        AND e.name LIKE CONCAT('%', #{name}, '%')


        AND e.category_id = #{categoryId}


        AND e.brand LIKE CONCAT('%', #{brand}, '%')


        AND e.status = #{status}

mapper.update:
UPDATE equipment
name = #{name}, category_id = #{categoryId}, brand = #{brand}, model = #{model}, serial_number = #{serialNumber}, location = #{location}, responsible_person = #{responsiblePerson}, quantity = #{quantity}, available_quantity = #{availableQuantity}, status = #{status}, cover_image = #{coverImage}, remark = #{remark},
WHERE id = #{id}

UPDATE equipment
SET quantity = quantity + #{quantity},
    available_quantity = available_quantity + #{quantity}
WHERE id = #{id}

UPDATE equipment
SET available_quantity = available_quantity - #{quantity}
WHERE id = #{id}
  AND available_quantity >= #{quantity}

UPDATE equipment
SET available_quantity = LEAST(quantity, available_quantity + #{quantity})
WHERE id = #{id}
